/*
 * icons.h
 * Small set of Google Material Symbols (outlined), sourced from
 * Google's own open-source material-design-icons repo
 * (github.com/google/material-design-icons, Apache 2.0 license)
 * and rasterized to 32x32 1-bit bitmaps for Arduino_GFX's
 * drawBitmap(x, y, bitmap, w, h, color) - draw with any color,
 * transparent background by construction (1-bit = icon or nothing).
 *
 * This is a starting set for the highest-impact UI surfaces, not
 * exhaustive OS-wide coverage - see the chat for which screens use
 * these so far and what's still text-only.
 */
#pragma once
#include <stdint.h>

#define ICON_SIZE 32

// Deliberately NOT const: these are read continuously, every frame,
// by the settings list while scrolling - a much wider and more
// frequent read-window than anything else in this project touches.
// const/static data here lives in flash-mapped read-only memory,
// which briefly becomes inaccessible whenever anything (including
// the BLE stack's own internal NVS writes, on its own FreeRTOS task,
// independent of any application code) writes to flash - any read
// of flash-mapped memory during that window crashes with a real,
// confirmed ESP32 "Cache error" panic. Living in ordinary RAM
// instead removes that hazard entirely for the data most exposed to
// it. The extra ~1.5KB of RAM this costs is trivial next to removing
// a real crash.

